def compute(vars):
    values = [vars["v1"], vars["v2"], vars["v3"]]
    count = len(values)
    if count == 0:
        return None

    total = sum(values)
    average = total / count

    return {
        "value": average,
        "trace": {
            "values": values,
            "count": count,
            "total": total,
            "output_meta": {
                "currency": "$",
                "scale": "thousands",
                "unit": "currency"
            }
        }
    }
